function usePersistent<T>(key:string, initial:T) {
  const [value,setValue] = useState<T>(() => {
    try { const stored = localStorage.getItem(key); return stored ? JSON.parse(stored) : initial; } catch { return initial; }
  });
  useEffect(() => localStorage.setItem(key, JSON.stringify(value)), [key,value]);
  return [value,setValue] as const;
}

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen,setMobileOpen] = useState(false);
  const current = nav.flatMap(x=>x.items).find(x => location === x[0] || location.startsWith(`${x[0]}/`));
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}>
      <div className="brand-mark"><div className="brand-symbol">+</div><div><div className="brand-name">MediCart<span style={{color:'hsl(var(--sidebar-primary))'}}>.</span></div><div className="brand-sub">Commerce command</div></div></div>
      <div style={{padding:'12px 20px 2px',fontSize:10,color:'hsl(var(--sidebar-foreground)/.45)',letterSpacing:'.12em',textTransform:'uppercase'}}>Workspace</div>
      {nav.map(group=><div key={group.section}><div className="nav-section">{group.section}</div>{group.items.map(([href,label,Icon])=><Link key={href} href={href} data-testid={`link-${label.toLowerCase().replaceAll(' ','-')}`} className={`nav-link ${current?.[0]===href ? 'active':''}`} onClick={()=>setMobileOpen(false)}><Icon className="nav-icon"/><span>{label}</span>{href==='/notifications' && <span style={{marginLeft:'auto',background:'hsl(var(--accent))',color:'hsl(var(--accent-foreground))',borderRadius:99,fontSize:9,padding:'2px 5px'}}>4</span>}</Link>)}</div>)}
      <div className="user-block"><div className="avatar">AS</div><div style={{minWidth:0}}><div style={{fontSize:12,fontWeight:700,color:'white'}}>Arjun Sethi</div><div style={{fontSize:10,color:'hsl(var(--sidebar-foreground)/.58)',marginTop:2}}>Store administrator</div></div><ChevronDown size={14} style={{marginLeft:'auto',color:'hsl(var(--sidebar-foreground)/.5)'}}/></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><div style={{display:'flex',alignItems:'center',gap:12}}><button className="icon-btn mobile-menu" aria-label="Open navigation" data-testid="button-open-navigation" onClick={()=>setMobileOpen(true)}><Menu size={18}/></button><div><div className="top-title">{current?.[1] || 'Commerce command'}</div><div className="breadcrumbs">MediCart / {current?.[1] || 'Overview'}</div></div></div><div className="top-actions"><button className="icon-btn" aria-label="Search" data-testid="button-global-search"><Search size={16}/></button><Link href="/notifications" className="icon-btn" aria-label="Notifications" data-testid="link-notifications"><Bell size={16}/></Link><div className="avatar" style={{width:30,height:30}}>AS</div></div></header>{children}
    </main>
  </div>;
}

function Page({ title, description, actions, children }: {title:string;description?:string;actions?:ReactNode;children:ReactNode}) {
  return <section className="page"><div className="page-heading"><div><h1 data-testid={`text-page-title-${title.toLowerCase().replaceAll(' ','-')}`}>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="heading-actions">{actions}</div>}</div>{children}</section>;
}
function Button({ children, primary=false, onClick, className='', testId }: {children:ReactNode;primary?:boolean;onClick?:()=>void;className?:string;testId?:string}) {
  return <button className={`btn ${primary?'btn-primary':''} ${className}`} onClick={onClick} data-testid={testId}>{children}</button>;
}
function Status({ children }: {children:string}) { return <span className={`status status-${children.toLowerCase().replaceAll(' ','-')}`}>{children}</span>; }
function Toast({ text, onClose }: {text:string;onClose:()=>void}) { useEffect(()=>{const t=setTimeout(onClose,2600);return()=>clearTimeout(t)},[onClose]); return <div className="toast" data-testid="status-toast"><CheckCircle2 size={15} style={{verticalAlign:'-3px',marginRight:7,color:'hsl(var(--sidebar-primary))'}}/>{text}</div>; }
function SearchBar({ value,onChange,placeholder='Search...' }: {value:string;onChange:(v:string)=>void;placeholder?:string}) { return <div className="search"><Search/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} data-testid="input-search"/></div>; }
function Empty({ icon:Icon=Package, title='Nothing here yet', detail='Records will appear here as your store grows.' }: {icon?:typeof Package;title?:string;detail?:string}) { return <div className="empty"><Icon size={28}/><strong>{title}</strong><span>{detail}</span></div>; }

